(()=>{let batouf=false;function fields(){const t=I18N.t,year=2026;return `<div class="form-section-title"><span>01</span><h3>${t('بيانات المشارك')}</h3></div><div class="form-grid"><label>${t('الاسم الثلاثي')}<input name="name" required minlength="5" maxlength="100" autocomplete="name"></label><label>${t('اسم المدرسة')}${batouf?`<select name="school" required><option value="">${t('اختر المدرسة')}</option>${StudentPolicy.schools.map(v=>`<option value="${v}">${t(v)}</option>`).join('')}</select>`:`<input name="school" required minlength="2" maxlength="150">`}</label><label>${t('الصف')}${batouf?`<select name="schoolClass" required><option value="">${t('اختر الصف')}</option>${StudentPolicy.classes.map(v=>`<option value="${v}">${t(v)}</option>`).join('')}</select>`:`<input name="schoolClass" required maxlength="40" placeholder="${t('مثال: السادس أ')}">`}</label>${batouf?'':`<label>${t('سنة الميلاد')}<input name="birthYear" type="number" required min="1926" max="2026" inputmode="numeric"></label>`}<label>${t('رقم هوية المشارك')}<input name="nationalId" type="text" required pattern="[0-9]{9}" maxlength="9" inputmode="numeric" dir="ltr" autocomplete="off"><small>${t('9 أرقام؛ لا يظهر رقم الهوية للزوار.')}</small></label>${batouf?'':`<label>${t('البلد')}<input name="country" required minlength="2" maxlength="80" autocomplete="address-level2"></label>`}<label>${t('ذكر / أنثى')}<select name="gender" required><option value="">${t('اختر')}</option><option value="male">${t('ذكر')}</option><option value="female">${t('أنثى')}</option></select></label><label>${t('مقاس البلوزة')}<select name="shirtSize" required><option value="">${t('اختر المقاس')}</option>${StudentPolicy.sizes.map(s=>`<option value="${s}">${s}</option>`).join('')}</select></label>${batouf?'':`<label>${t('المسافة')}<select name="distance" required></select><small>${t('المسافات تُعلن لاحقًا؛ التسجيل مبدئي.')}</small></label>`}</div><div class="form-section-title"><span>02</span><h3>${t('بيانات ولي الأمر')}</h3></div><div class="form-grid"><label>${t('اسم ولي الأمر')}<input name="guardianName" required minlength="5" maxlength="100" autocomplete="name"></label><label>${t('هاتف ولي الأمر')}<input name="guardianPhone" type="tel" required maxlength="20" dir="ltr" placeholder="0501234567 / +972501234567" autocomplete="tel"></label><label>${t('البريد الإلكتروني (اختياري)')}<input name="email" type="email" maxlength="254" dir="ltr" autocomplete="email"></label></div><label class="check consent-card"><input name="guardianConsent" type="checkbox" required>${t('أقرّ بأن ولي الأمر يعلم بالمشاركة ويوافق عليها.')}</label><div class="form-section-title"><span>03</span><h3>${t('تصريح طبي')}</h3></div><div class="medical-declaration" tabindex="0">${t(StudentPolicy.text).split('\n').join('<br>')}</div><label class="check consent-card"><input name="medicalConsent" type="checkbox" required>${t('قرأت التصريح والإقرار أعلاه وأوافق عليه.')}</label><div class="form-section-title"><span>04</span><h3>${t('التواصل والتذكير (اختياري)')}</h3></div><label class="check consent-card"><input name="smsConsent" type="checkbox">${t('أوافق على رسالة SMS بعد التسجيل وتذكير قبل السباق بـ24 ساعة على هاتف ولي الأمر.')}</label><label class="check"><input name="emailConsent" type="checkbox">${t('أوافق على استلام تذكير عبر البريد الإلكتروني')}</label><label class="check"><input name="whatsappConsent" type="checkbox">${t('أوافق على استلام تذكير عبر واتساب')}</label><p class="muted">${t('بيانات الطالب والهوية والتصريح متاحة للأدمن فقط. التذكير يُرسل لولي الأمر بعد تفعيل الخدمة وتحديد ساعة السباق.')}</p><button class="btn" id="submitBtn" type="submit">${t('تأكيد التسجيل المجاني')}</button><p id="formStatus" role="status" aria-live="polite"></p><div id="registrationSuccess" hidden></div>`}let originalForm=null;window.StudentForm={apply(form,event){if(originalForm===null)originalForm=form.innerHTML;if(event?.registrationProfile!=='student'){if(form.dataset.studentForm==='true'){form.innerHTML=originalForm;delete form.dataset.studentForm}return;}if(form.dataset.studentForm==='true')return;batouf=event.id==='arraba-2026';form.innerHTML=fields();form.dataset.studentForm='true'},payload(fd){return {school:fd.get('school'),schoolClass:fd.get('schoolClass'),birthYear:fd.get('birthYear'),nationalId:fd.get('nationalId'),country:fd.get('country'),gender:fd.get('gender'),shirtSize:fd.get('shirtSize'),guardianName:fd.get('guardianName'),guardianPhone:fd.get('guardianPhone'),smsConsent:fd.has('smsConsent'),guardianConsent:fd.has('guardianConsent'),medicalConsent:fd.has('medicalConsent'),policyVersion:StudentPolicy.version}}};window.addEventListener('languagechange',()=>{const form=document.querySelector('#registrationForm');if(form?.dataset.studentForm!=='true')return;const values=new FormData(form),success=document.querySelector('#registrationSuccess')?.innerHTML,hidden=document.querySelector('#registrationSuccess')?.hidden;form.innerHTML=fields();for(const [k,v]of values){const field=form.elements[k];if(field){if(field.type==='checkbox')field.checked=true;else if(k==='distance'){field.add(new Option(I18N.distance(v),v));field.value=v}else field.value=v}}window.dispatchEvent(new CustomEvent('studentformtranslated'));if(success){document.querySelector('#registrationSuccess').innerHTML=success;document.querySelector('#registrationSuccess').hidden=hidden}})})();
